const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const namibia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Namibia'))
    .geometry();
  const startDate = '2021-01-01';
  const endDate = '2021-02-01';

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(namibia);

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log("Evidence: No CHIRPS images found for January 2021 in Namibia.");
    console.log("C1");
    return;
  }
  console.log(`Evidence: Found ${imageCount} daily CHIRPS images.`);

  // 3. Processing
  // Sum all daily precipitation images to get a monthly total
  const totalPrecipitationMm = collection.select('precipitation').sum();

  // 4. Calculation
  // Calculate the average precipitation over the country. Use a large scale to avoid timeout.
  const stats = totalPrecipitationMm.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  });

  const avgPrecipitationMm = stats.get('precipitation').getInfo();
  const validPixelCount = totalPrecipitationMm.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (validPixelCount === 0) {
      console.log("Evidence: Found images but no valid pixels after processing.");
      console.log("C2");
      return;
  }

  if (avgPrecipitationMm === null || avgPrecipitationMm === undefined) {
    console.log("Evidence: Could not calculate average precipitation. Result was null.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  // Convert mm to inches (1 inch = 25.4 mm)
  const avgPrecipitationInches = avgPrecipitationMm / 25.4;
  const thresholdInches = 7;

  console.log(`Evidence: Average rainfall was ${avgPrecipitationMm.toFixed(2)} mm.`);
  console.log(`Evidence: This is equivalent to ${avgPrecipitationInches.toFixed(2)} inches.`);
  console.log(`Evidence: The threshold for the question is > ${thresholdInches} inches.`);
  console.log(`Evidence: Pixel count for analysis: ${validPixelCount}`);

  if (avgPrecipitationInches > thresholdInches) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
